```typescript
// ANGULAR: a component is a class + template + metadata. More ceremony.
@Component({
  selector: 'app-hello',
  template: `<h1>{{name}}</h1>`,
})
export class HelloComponent { name = 'World'; }

// REACT: a component is a function returning JSX. Less ceremony.
function Hello() {
  const [name] = useState('World');
  return <h1>{name}</h1>;
}
//   Angular gives you routing/forms/DI for free; React makes you add them.
```
